// ---------------------------------------------------------------------------
// United Kingdom listings (Nov 2026).
//
// HONESTY RULES (same as the Swiss data):
//  * verified: true  → checked with a web search on 11 Nov 2026 (see `source`).
//  * verified: false → a real, long-running UK programme or organisation
//    written from existing knowledge; dates, ages and costs NOT checked yet.
//  * Many UK programmes are only for UK *state-school* students or only run in
//    one nation (England, Scotland, Wales, Northern Ireland). The eligibility
//    text says so, and `cantons` limits nation-only programmes.
//  * Known closures are left out on purpose: NCS (National Citizen Service)
//    closed on 31 March 2025.
//  * Town and region cards ("find X near you") point to a web search and are
//    always verified: false.
// ---------------------------------------------------------------------------

const search = (q) => 'https://duckduckgo.com/?q=' + encodeURIComponent(q);
const slug = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const SRC = 'Well-known UK programme — details not checked in this session (Nov 2026)';
const CHECKED = 'Checked with a web search, 11 Nov 2026';

const ENG = ['UK-LDN', 'UK-SE', 'UK-SW', 'UK-EE', 'UK-EM', 'UK-WM', 'UK-YH', 'UK-NW', 'UK-NE'];
const SCT = ['UK-SCT'];
const WLS = ['UK-WLS'];
const NIR = ['UK-NIR'];
const STATE = 'UK state-school (non-fee-paying) students only.';

// National UK listing.
const U = (o) => ({
  country: 'GB', scope: 'national', format: 'in-person', city: null, canton: null,
  minAge: 11, maxAge: 18, cost: 'See the website', commitment: 'Varies',
  timing: 'See the website for current dates',
  eligibility: 'Students living in the UK — see the website for details.',
  verified: false, source: SRC,
  ...o,
  ...(o.url || o.searchUrl ? {} : { searchUrl: search(o.title + ' UK') }),
});
const OLY = (id, title, org, cats, skills, description, extra = {}) => U({
  id, title, org, type: 'Academic competition', categories: cats, skills, minAge: 11, maxAge: 19,
  eligibility: 'UK school students; usually entered through your school — ask your teacher.',
  description, details: 'The first round is usually sat at school. The best students go on to further rounds, training camps and the chance to represent the UK internationally.',
  timing: 'First rounds are usually in autumn or winter — check the website', cost: 'Usually free or a small school entry fee',
  ...extra,
});
const UNI = (id, uni, title, description, extra = {}) => U({
  id, title, org: uni, type: 'University programme', categories: ['academic'], skills: ['Research', 'Communication'],
  minAge: 15, maxAge: 18,
  eligibility: 'Usually Year 12 (S5 in Scotland, Year 13 in Northern Ireland); many places prioritise state-school students and under-represented groups.',
  description, timing: 'Applications usually open in winter or spring for the summer', cost: 'Usually free',
  ...extra,
});
const ESSAY = (id, title, org, description, extra = {}) => U({
  id, title, org, type: 'Academic competition', categories: ['academic', 'arts'], skills: ['Writing', 'Research'],
  minAge: 13, maxAge: 18, format: 'online', description, cost: 'Free',
  ...extra,
});
const VOL = (id, title, org, description, extra = {}) => U({
  id, title, org, type: 'Volunteering', categories: ['volunteering'], skills: ['Teamwork', 'Communication'],
  minAge: 14, maxAge: 25, description, cost: 'Free', ...extra,
});
const ARTS = (id, title, org, description, extra = {}) => U({
  id, title, org, type: 'Arts ensemble', categories: ['arts'], skills: ['Creativity', 'Teamwork'],
  minAge: 11, maxAge: 19, description, ...extra,
});
const NOTE = 'CVAscender does not recommend any bank. Compare fees, age limits and conditions and talk to a parent before opening an account.';
const BANK = (id, name, url, description, minAge = 11, maxAge = 17) => U({
  id, title: `${name} — account for young people`, org: name, type: 'Youth bank account', categories: ['business'], skills: ['Project management'],
  minAge, maxAge, eligibility: 'Age limits and parental consent rules differ — check with the provider.',
  description, details: NOTE, timing: 'Open any time', commitment: 'Ongoing', cost: 'Check fees and conditions', url,
});

